from taf.gnb.oam.megazone_client.rbts import ResourceBTS

try:
    import unittest2 as unittest
except ImportError:
    import unittest

try:
    from mock import Mock
except ImportError:
    from unittest.mock import Mock


class TestResourceBTSWithGivenFaults(unittest.TestCase):
    def setUp(self):
        self.fault_response = {
            "specificProblem": "specificProblem",
            "alarmText": "alarmText",
            "perceivedSeverity": "perceivedSeverity",
            "additionalText1": "additionalText1",
            "isRCP": False
        }

        self.response_mock = Mock()
        self.response_mock.json = Mock(return_value=[self.fault_response])
        self.session_mock = Mock()
        self.session_mock.send_request = Mock(return_value=self.response_mock)
        self.bts = ResourceBTS(session=self.session_mock)

    def test_get_faults_shouldSendRequestWithGivenState(self):
        self.bts.get_faults(state="test")
        self.assertEqual(self.session_mock.send_request.call_args[0][0], "mz/r/v1/alarm?state=test")

    def test_get_faults_shouldSendRequestWith_unverified_GET_method(self):
        self.bts.get_faults(state="test")
        self.assertEqual(self.session_mock.send_request.call_args[1]['method'], 'GET')
        self.assertEqual(self.session_mock.send_request.call_args[1]['verify'], False)

    def test_get_faults_shouldReturnListWithFaults(self):
        expected = [{
            "specificProblem": "specificProblem",
            "alarmText": "alarmText",
            "perceivedSeverity": "perceivedSeverity",
            "additionalText1": "additionalText1",
            "isRCP": False
        }]
        result = self.bts.get_faults(state="test")
        self.assertIsInstance(result, list)
        self.assertEqual(result, expected)


class TestResourceBTSWithGivenRcpAlarms(unittest.TestCase):
    def setUp(self):
        self.rcpAlarm_response = {
            "specificProblem": "specificProblem",
            "alarmText": "alarmText",
            "perceivedSeverity": "perceivedSeverity",
            "additionalText1": "additionalText1",
            "additionalText8": "additionalText8",
            "isRCP": True
        }

        self.response_mock = Mock()
        self.response_mock.json = Mock(return_value=[self.rcpAlarm_response])
        self.session_mock = Mock()
        self.session_mock.send_request = Mock(return_value=self.response_mock)
        self.bts = ResourceBTS(session=self.session_mock)

    def test_getFaults_shouldReturnEmptyList(self):
        self.response_mock.json = Mock(return_value=[self.rcpAlarm_response])
        self.assertEqual(self.bts.get_faults(state="test"), [])

    def test_get_alarms_shouldReturnRelevantDataFromAlarm(self):
        expected_output = [{
            "specificProblem": "specificProblem",
            "alarmText": "alarmText",
            "perceivedSeverity": "perceivedSeverity",
            "additionalText1": "additionalText1",
            "additionalText8": "additionalText8",
            "isRCP": True
        }]
        self.assertEqual(self.bts.get_alarms(), expected_output)
